#!/bin/bash
set -eu
exec env -u DOCKER_HOST -u DOCKER_CONTEXT -u DOCKER_TLS -u DOCKER_TLS_VERIFY -u DOCKER_CERT_PATH docker --host=unix:///var/run/docker.sock run --rm --memory=12g --memory-swap=12g --cpus=1 --user 1000:1000 --mount type=bind,src=/usr,dst=/usr,readonly --mount type=bind,src=/opt,dst=/opt,readonly --mount type=bind,src=/workspace,dst=/workspace --mount type=bind,src=/tmp/solidity-lean-feature-groups-20261025,dst=/tmp/solidity-lean-feature-groups-20261025 --workdir /workspace/solidity-lean ubuntu:24.04 bash -c 'source /workspace/.setup/activate.sh; export LEAN_NUM_THREADS=1; export PATH=/workspace/.setup/world-bin:/opt/codex/runtimes/codex-primary-runtime/dependencies/node/bin:$PATH; flock -n /tmp/solidity-lean-feature-groups-20261025/writer.lock bash -c "$1"; code=$?; echo "cgroup memory.peak=$(cat /sys/fs/cgroup/memory.peak)"; exit $code' bash "$1"
